param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$out=Join-Path $root 'outputs';$organized=Join-Path $out 'organized';if(Test-Path -LiteralPath $organized){Remove-Item -LiteralPath $organized -Recurse -Force};foreach($old in @('file-movement-log.csv','organized-backup.zip','summary.json','error.log')){$oldPath=Join-Path $out $old;if(Test-Path -LiteralPath $oldPath){Remove-Item -LiteralPath $oldPath -Force}};New-Item -ItemType Directory -Force -Path $organized | Out-Null
function Assert-InRoot($path){$full=[IO.Path]::GetFullPath($path);$base=([IO.Path]::GetFullPath($root)).TrimEnd('\')+'\';if(-not $full.StartsWith($base,[StringComparison]::OrdinalIgnoreCase)){throw "Path escaped project root: $full"};return $full}
try{$map=@{'.pdf'='PDF';'.docx'='DOCX';'.xlsx'='XLSX';'.png'='Images';'.jpg'='Images';'.txt'='Text'};$moves=@();$moved=0;$skipped=0;foreach($file in Get-ChildItem $input -File -Recurse|Where-Object{$_.FullName -notlike "$organized*"}){$ext=$file.Extension.ToLowerInvariant();if(-not $map.ContainsKey($ext)){$skipped++;$moves+=[pscustomobject]@{Source=$file.FullName.Substring($root.Length+1);Destination='';Category='Skipped';Status='Unsupported extension'};continue};$folder=Join-Path $organized $map[$ext];New-Item -ItemType Directory -Force -Path $folder|Out-Null;$candidate=Join-Path $folder $file.Name;$n=1;while(Test-Path $candidate){$candidate=Join-Path $folder ($file.BaseName+'__duplicate'+$n+$file.Extension);$n++};Assert-InRoot $candidate|Out-Null;Copy-Item $file.FullName $candidate;$moved++;$moveStatus='Copied';if($n -gt 1){$moveStatus='Copied with duplicate-safe name'};$moves+=[pscustomobject]@{Source=$file.FullName.Substring($root.Length+1);Destination=$candidate.Substring($root.Length+1);Category=$map[$ext];Status=$moveStatus}};$moves|Export-Csv (Join-Path $out 'file-movement-log.csv') -NoTypeInformation;$zipPath=Join-Path $out 'organized-backup.zip';if(Test-Path $zipPath){Remove-Item $zipPath -Force};$files=@(Get-ChildItem $organized -File -Recurse);if($files.Count -eq 0){throw 'No files were organized'};Compress-Archive -Path (Join-Path $organized '*') -DestinationPath $zipPath -Force;Add-Type -AssemblyName System.IO.Compression.FileSystem;$z=[IO.Compression.ZipFile]::OpenRead($zipPath);$zipCount=@($z.Entries|Where-Object{-not $_.FullName.EndsWith('/')}).Count;$z.Dispose();$summary=[pscustomobject]@{MovedFiles=$moved;SkippedFiles=$skipped;OrganizedFiles=$files.Count;ZipEntries=$zipCount;ZipVerified=($zipCount -eq $files.Count);DuplicateSafeNames=@($moves|Where-Object{$_.Status -like '*duplicate*'}).Count;RootBoundaryVerified=$true};$summary|ConvertTo-Json|Set-Content (Join-Path $out 'summary.json') -Encoding UTF8;if(-not $summary.ZipVerified){throw 'ZIP entry count mismatch'};Write-Output "Copied $moved files, skipped $skipped, and verified $zipCount ZIP entries."}catch{$_|Out-String|Set-Content (Join-Path $out 'error.log');throw}
